#!/usr/bin/env python3

"""
NIXAL — REGISTRO DE OPERAÇÕES SOBRE CONTEXTO

Microetapa 56.3.10

Objetivos:

1. Carregar o catálogo formal de operações sobre contexto.
2. Validar a estrutura das operações.
3. Expor especificações das operações.
4. Permitir descobrir quais operações de contexto existem.
5. Manter separação entre:
   - capacidades: ações executáveis no sistema;
   - operações de contexto: transformações sobre informação
     que já está disponível.
6. Não executar operações neste módulo.

Por enquanto o catálogo contém somente:

    selecionar
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any


ARQUIVO_OPERACOES = Path(
    "operacoes_contexto_nixal.json"
)


@dataclass
class OperacaoContexto:
    nome: str
    descricao: str
    objetivo: str
    tipo_entrada: str
    tipo_saida: str
    argumentos: dict[str, Any] = field(
        default_factory=dict
    )
    regras: list[str] = field(
        default_factory=list
    )
    exemplos: list[str] = field(
        default_factory=list
    )


class OperacoesContextoNixal:

    def __init__(
        self,
        arquivo: Path = ARQUIVO_OPERACOES,
    ) -> None:

        self.arquivo = arquivo

        self.operacoes = (
            self._carregar_catalogo()
        )

        self.mapa_operacoes = {
            operacao.nome: operacao
            for operacao in self.operacoes
        }

    # ============================================================
    # NORMALIZAÇÃO
    # ============================================================

    @staticmethod
    def _texto(
        valor: Any,
        campo: str,
    ) -> str:

        if not isinstance(
            valor,
            str,
        ):

            raise ValueError(
                f"O campo '{campo}' precisa "
                "ser uma string."
            )

        valor = valor.strip()

        if not valor:

            raise ValueError(
                f"O campo '{campo}' não pode "
                "ser vazio."
            )

        return valor

    @staticmethod
    def _lista_textos(
        valor: Any,
        campo: str,
    ) -> list[str]:

        if not isinstance(
            valor,
            list,
        ):

            raise ValueError(
                f"O campo '{campo}' precisa "
                "ser uma lista."
            )

        resultado = []

        for item in valor:

            if not isinstance(
                item,
                str,
            ):

                raise ValueError(
                    f"Todos os itens de '{campo}' "
                    "precisam ser strings."
                )

            item = item.strip()

            if item:

                resultado.append(
                    item
                )

        return resultado

    @staticmethod
    def _objeto(
        valor: Any,
        campo: str,
    ) -> dict[str, Any]:

        if not isinstance(
            valor,
            dict,
        ):

            raise ValueError(
                f"O campo '{campo}' precisa "
                "ser um objeto."
            )

        return dict(
            valor
        )

    # ============================================================
    # CARREGAMENTO
    # ============================================================

    def _carregar_catalogo(
        self,
    ) -> list[OperacaoContexto]:

        if not self.arquivo.exists():

            raise FileNotFoundError(
                "Arquivo "
                "operacoes_contexto_nixal.json "
                "não encontrado."
            )

        try:

            with self.arquivo.open(
                "r",
                encoding="utf-8",
            ) as arquivo:

                dados = json.load(
                    arquivo
                )

        except json.JSONDecodeError as erro:

            raise ValueError(
                "operacoes_contexto_nixal.json "
                f"possui JSON inválido: {erro}"
            ) from erro

        if not isinstance(
            dados,
            list,
        ):

            raise ValueError(
                "operacoes_contexto_nixal.json "
                "precisa conter uma lista."
            )

        operacoes = []

        for indice, item in enumerate(
            dados,
            start=1,
        ):

            if not isinstance(
                item,
                dict,
            ):

                raise ValueError(
                    f"A operação {indice} "
                    "não é um objeto JSON."
                )

            nome = self._texto(
                item.get("nome"),
                "nome",
            )

            descricao = self._texto(
                item.get("descricao"),
                "descricao",
            )

            objetivo = self._texto(
                item.get("objetivo"),
                "objetivo",
            )

            tipo_entrada = self._texto(
                item.get("tipo_entrada"),
                "tipo_entrada",
            )

            tipo_saida = self._texto(
                item.get("tipo_saida"),
                "tipo_saida",
            )

            argumentos = self._objeto(
                item.get(
                    "argumentos",
                    {},
                ),
                "argumentos",
            )

            regras = self._lista_textos(
                item.get(
                    "regras",
                    [],
                ),
                "regras",
            )

            exemplos = self._lista_textos(
                item.get(
                    "exemplos",
                    [],
                ),
                "exemplos",
            )

            if nome in {
                operacao.nome
                for operacao in operacoes
            }:

                raise ValueError(
                    f"A operação '{nome}' "
                    "está duplicada."
                )

            operacoes.append(
                OperacaoContexto(
                    nome=nome,
                    descricao=descricao,
                    objetivo=objetivo,
                    tipo_entrada=tipo_entrada,
                    tipo_saida=tipo_saida,
                    argumentos=argumentos,
                    regras=regras,
                    exemplos=exemplos,
                )
            )

        if not operacoes:

            raise ValueError(
                "Nenhuma operação de contexto "
                "válida foi encontrada."
            )

        return operacoes

    # ============================================================
    # CONSULTA
    # ============================================================

    def listar_operacoes(
        self,
    ) -> list[dict[str, Any]]:

        resultado = []

        for operacao in self.operacoes:

            resultado.append(
                {
                    "nome": operacao.nome,
                    "descricao": operacao.descricao,
                    "objetivo": operacao.objetivo,
                    "tipo_entrada": operacao.tipo_entrada,
                    "tipo_saida": operacao.tipo_saida,
                    "argumentos": operacao.argumentos,
                    "regras": operacao.regras,
                    "exemplos": operacao.exemplos,
                }
            )

        return resultado

    def obter_operacao(
        self,
        nome: str,
    ) -> OperacaoContexto | None:

        if not isinstance(
            nome,
            str,
        ):

            return None

        nome = nome.strip()

        if not nome:

            return None

        return self.mapa_operacoes.get(
            nome
        )

    def obter_especificacao(
        self,
        nome: str,
    ) -> dict[str, Any] | None:

        operacao = self.obter_operacao(
            nome
        )

        if operacao is None:

            return None

        return {
            "nome": operacao.nome,
            "descricao": operacao.descricao,
            "objetivo": operacao.objetivo,
            "tipo_entrada": operacao.tipo_entrada,
            "tipo_saida": operacao.tipo_saida,
            "argumentos": operacao.argumentos,
            "regras": operacao.regras,
            "exemplos": operacao.exemplos,
        }

    def validar_argumentos(
        self,
        nome: str,
        argumentos: dict[str, Any],
    ) -> dict[str, Any]:

        operacao = self.obter_operacao(
            nome
        )

        if operacao is None:

            return {
                "valido": False,
                "erro": (
                    f"Operação de contexto "
                    f"'{nome}' não existe."
                ),
            }

        if not isinstance(
            argumentos,
            dict,
        ):

            return {
                "valido": False,
                "erro": (
                    "Os argumentos da operação "
                    "precisam ser um objeto."
                ),
            }

        especificacao = (
            operacao.argumentos
        )

        for nome_argumento, contrato in (
            especificacao.items()
        ):

            if not isinstance(
                contrato,
                dict,
            ):

                continue

            obrigatorio = (
                contrato.get(
                    "obrigatorio",
                    False,
                )
            )

            if (
                obrigatorio
                and nome_argumento not in argumentos
            ):

                return {
                    "valido": False,
                    "erro": (
                        f"O argumento obrigatório "
                        f"'{nome_argumento}' não foi fornecido."
                    ),
                }

        return {
            "valido": True,
            "erro": None,
        }


# ================================================================
# MAIN
# ================================================================

def main() -> None:

    registro = (
        OperacoesContextoNixal()
    )

    print()
    print("=" * 60)
    print(
        "NIXAL — OPERAÇÕES SOBRE CONTEXTO"
    )
    print("=" * 60)

    print()

    print(
        "OPERAÇÕES DISPONÍVEIS:"
    )

    for operacao in (
        registro.listar_operacoes()
    ):

        print()
        print(
            f"Nome: {operacao['nome']}"
        )

        print(
            f"Descrição: "
            f"{operacao['descricao']}"
        )

        print(
            f"Objetivo: "
            f"{operacao['objetivo']}"
        )

        print(
            f"Entrada: "
            f"{operacao['tipo_entrada']}"
        )

        print(
            f"Saída: "
            f"{operacao['tipo_saida']}"
        )

        print(
            "Argumentos:"
        )

        print(
            json.dumps(
                operacao["argumentos"],
                ensure_ascii=False,
                indent=2,
            )
        )

        print(
            "Regras:"
        )

        for regra in operacao[
            "regras"
        ]:

            print(
                f"- {regra}"
            )

        print(
            "Exemplos:"
        )

        for exemplo in operacao[
            "exemplos"
        ]:

            print(
                f"- {exemplo}"
            )

    print()
    print("=" * 60)
    print(
        "TESTE DE EXISTÊNCIA DA OPERAÇÃO"
    )
    print("=" * 60)

    especificacao = (
        registro.obter_especificacao(
            "selecionar"
        )
    )

    print(
        json.dumps(
            especificacao,
            ensure_ascii=False,
            indent=2,
        )
    )

    print()
    print("=" * 60)
    print(
        "TESTE DE ARGUMENTOS"
    )
    print("=" * 60)

    validacao = (
        registro.validar_argumentos(
            "selecionar",
            {
                "consulta": (
                    "capacidades_nixal.json"
                )
            },
        )
    )

    print(
        json.dumps(
            validacao,
            ensure_ascii=False,
            indent=2,
        )
    )

    print()
    print("=" * 60)
    print(
        "TESTE DE OPERAÇÃO INEXISTENTE"
    )
    print("=" * 60)

    inexistente = (
        registro.obter_especificacao(
            "operacao_inexistente"
        )
    )

    print(
        json.dumps(
            {
                "encontrada": (
                    inexistente is not None
                )
            },
            ensure_ascii=False,
            indent=2,
        )
    )


if __name__ == "__main__":
    main()

#!/usr/bin/env python3

"""
NIXAL — EXECUTOR DE OPERAÇÕES SOBRE CONTEXTO

Microetapa 56.3.10

Objetivos:

1. Executar operações declaradas no catálogo de contexto.
2. Separar execução de operação de registro de operação.
3. Nunca executar capacidades.
4. Operar somente sobre informação já presente no contexto.
5. Recusar informação ausente.
6. Recusar seleção ambígua.
7. Preservar o contexto original sem modificá-lo.
8. Permitir seleção de informação estruturada, não apenas arquivos.
9. Manter seleção explícita de arquivos como caso especializado.
10. Nunca criar informação nova durante uma operação de contexto.

Operação implementada nesta etapa:

    selecionar
"""

from __future__ import annotations

import json
import re
from typing import Any

from nixal_operacoes_contexto import (
    OperacoesContextoNixal,
)


STOPWORDS = {
    "a",
    "o",
    "os",
    "as",
    "um",
    "uma",
    "uns",
    "umas",
    "de",
    "da",
    "do",
    "das",
    "dos",
    "e",
    "ou",
    "em",
    "no",
    "na",
    "nos",
    "nas",
    "que",
    "qual",
    "quais",
    "me",
    "minha",
    "meu",
    "minhas",
    "meus",
    "para",
    "por",
    "com",
    "como",
    "está",
    "esta",
    "estao",
    "estão",
    "quero",
    "preciso",
    "saber",
    "descobrir",
    "isso",
    "nessa",
    "nesse",
    "do",
    "da",
    "ao",
    "aos",
    "às",
    "foi",
    "ser",
    "ter",
    "vai",
    "vou",
}


class ExecutorContextoNixal:

    def __init__(self) -> None:

        self.registro = (
            OperacoesContextoNixal()
        )

        self.implementacoes = {
            "selecionar": (
                self._executar_selecionar
            ),
        }

    # ============================================================
    # NORMALIZAÇÃO
    # ============================================================

    @staticmethod
    def _normalizar_texto(
        texto: str,
    ) -> str:

        texto = texto.lower()

        substituicoes = {
            "á": "a",
            "à": "a",
            "ã": "a",
            "â": "a",
            "é": "e",
            "ê": "e",
            "í": "i",
            "ó": "o",
            "ô": "o",
            "õ": "o",
            "ú": "u",
            "ç": "c",
        }

        for origem, destino in (
            substituicoes.items()
        ):

            texto = texto.replace(
                origem,
                destino,
            )

        texto = re.sub(
            r"[^a-z0-9_.-]+",
            " ",
            texto,
        )

        return texto.strip()

    @classmethod
    def _tokens(
        cls,
        texto: str,
    ) -> set[str]:

        normalizado = cls._normalizar_texto(
            texto
        )

        tokens: set[str] = set()

        for token in normalizado.split():

            token = token.strip(
                ".,;:!?\"'()[]{}"
            )

            if not token:
                continue

            if token in STOPWORDS:
                continue

            if len(token) < 3:
                continue

            if token.endswith("ões"):
                token = token[:-3]

            elif (
                token.endswith("s")
                and len(token) > 5
            ):
                token = token[:-1]

            tokens.add(token)

        return tokens

    # ============================================================
    # EXTRAÇÃO DE ARQUIVOS
    # ============================================================

    def _extrair_arquivos(
        self,
        valor: Any,
    ) -> list[str]:

        encontrados: list[str] = []

        def visitar(
            item: Any,
        ) -> None:

            if isinstance(
                item,
                dict,
            ):

                for valor_interno in item.values():

                    visitar(
                        valor_interno
                    )

                return

            if isinstance(
                item,
                list,
            ):

                for valor_interno in item:

                    visitar(
                        valor_interno
                    )

                return

            if isinstance(
                item,
                str,
            ):

                candidato = item.strip()

                if re.fullmatch(
                    r"[^/\n]+",
                    candidato,
                ) and "." in candidato:

                    if candidato not in encontrados:

                        encontrados.append(
                            candidato
                        )

        visitar(
            valor
        )

        return encontrados

    # ============================================================
    # CANDIDATOS DE INFORMAÇÃO
    # ============================================================

    def _serializar_candidato(
        self,
        valor: Any,
    ) -> str:

        if isinstance(
            valor,
            str,
        ):
            return valor

        try:

            return json.dumps(
                valor,
                ensure_ascii=False,
                sort_keys=True,
            )

        except (
            TypeError,
            ValueError,
        ):

            return str(valor)

    def _extrair_candidatos_informacao(
        self,
        contexto: dict[int, dict[str, Any]],
    ) -> list[dict[str, Any]]:

        candidatos: list[dict[str, Any]] = []

        def adicionar(
            *,
            etapa: int,
            valor: Any,
            caminho: str,
            tipo: str,
            prioridade: int,
        ) -> None:

            texto = self._serializar_candidato(
                valor
            )

            candidato = {
                "etapa": etapa,
                "valor": valor,
                "caminho": caminho,
                "tipo": tipo,
                "prioridade": prioridade,
                "texto": texto,
            }

            candidatos.append(
                candidato
            )

        for numero_etapa, registro in contexto.items():

            if not isinstance(
                numero_etapa,
                int,
            ):
                continue

            if not isinstance(
                registro,
                dict,
            ):
                continue

            if registro.get(
                "atendida"
            ) is not True:
                continue

            if registro.get(
                "sucesso_operacao"
            ) is not True:
                continue

            resultado = registro.get(
                "resultado"
            )

            if not isinstance(
                resultado,
                dict,
            ):
                continue

            if resultado.get(
                "sucesso"
            ) is not True:
                continue

            if "resultado" not in resultado:
                continue

            valor = resultado.get(
                "resultado"
            )

            adicionar(
                etapa=numero_etapa,
                valor=valor,
                caminho=(
                    f"etapa.{numero_etapa}"
                    ".resultado"
                    ".resultado"
                ),
                tipo=(
                    "informacao_estruturada"
                    if isinstance(
                        valor,
                        (dict, list),
                    )
                    else "informacao"
                ),
                prioridade=3,
            )

            # Um resultado em lista pode conter itens nomeáveis,
            # como arquivos. Esses itens são candidatos individuais
            # sem remover o candidato estrutural original.
            if isinstance(
                valor,
                list,
            ):

                for indice, item in enumerate(
                    valor
                ):

                    if isinstance(
                        item,
                        (str, int, float, bool),
                    ):

                        adicionar(
                            etapa=numero_etapa,
                            valor=item,
                            caminho=(
                                f"etapa.{numero_etapa}"
                                ".resultado.resultado"
                                f"[{indice}]"
                            ),
                            tipo="item",
                            prioridade=4,
                        )

        return candidatos

    # ============================================================
    # SELEÇÃO EXPLÍCITA DE ARQUIVO
    # ============================================================

    def _selecionar_arquivo_explicitamente(
        self,
        consulta: str,
        contexto: dict[int, dict[str, Any]],
    ) -> dict[str, Any] | None:

        arquivos = []

        for arquivo in self._extrair_arquivos(
            contexto
        ):

            if arquivo.lower().endswith(
                ".json"
            ):

                if arquivo not in arquivos:

                    arquivos.append(
                        arquivo
                    )

        if not arquivos:
            return None

        consulta_normalizada = (
            self._normalizar_texto(
                consulta
            )
        )

        nomes_mencionados = re.findall(
            r"[\w.-]+\.json",
            consulta_normalizada,
            re.IGNORECASE,
        )

        if not nomes_mencionados:
            return None

        nomes_encontrados = []

        for nome in nomes_mencionados:

            for arquivo in arquivos:

                if (
                    nome.lower()
                    == arquivo.lower()
                ):

                    if (
                        arquivo
                        not in nomes_encontrados
                    ):

                        nomes_encontrados.append(
                            arquivo
                        )

        # Um único nome explícito.
        if len(
            nomes_mencionados
        ) == 1:

            if len(
                nomes_encontrados
            ) == 1:

                return {
                    "sucesso": True,
                    "tipo": "contexto",
                    "operacao": "selecionar",
                    "valor": (
                        nomes_encontrados[0]
                    ),
                    "origem": "contexto",
                    "candidatos": arquivos,
                    "erro": None,
                }

            return {
                "sucesso": False,
                "tipo": "contexto",
                "operacao": "selecionar",
                "valor": None,
                "origem": "contexto",
                "candidatos": arquivos,
                "erro": (
                    "A informação solicitada "
                    "não existe no contexto."
                ),
            }

        # Mais de um nome explícito.
        if len(
            nomes_mencionados
        ) > 1:

            if len(
                nomes_encontrados
            ) == 1:

                return {
                    "sucesso": True,
                    "tipo": "contexto",
                    "operacao": "selecionar",
                    "valor": (
                        nomes_encontrados[0]
                    ),
                    "origem": "contexto",
                    "candidatos": arquivos,
                    "erro": None,
                }

            return {
                "sucesso": False,
                "tipo": "contexto",
                "operacao": "selecionar",
                "valor": None,
                "candidatos": arquivos,
                "erro": (
                    "A seleção explícita não pode "
                    "ser resolvida com segurança."
                ),
            }

        return None

    # ============================================================
    # SELEÇÃO DE INFORMAÇÃO GERAL
    # ============================================================

    def _pontuar_candidato(
        self,
        consulta: str,
        candidato: dict[str, Any],
    ) -> tuple[int, list[str]]:

        tokens_consulta = self._tokens(
            consulta
        )

        tokens_candidato = self._tokens(
            candidato["texto"]
        )

        intersecao = sorted(
            tokens_consulta
            & tokens_candidato
        )

        score = len(
            intersecao
        )

        # Informação estruturada ganha uma pequena prioridade
        # quando há empate com nomes de arquivo ou itens simples.
        if (
            candidato["tipo"]
            == "informacao_estruturada"
            and score > 0
        ):
            score += 1

        # A prioridade é apenas um desempate estrutural.
        score += max(
            0,
            5 - candidato["prioridade"],
        )

        return (
            score,
            intersecao,
        )

    def _executar_selecionar_informacao(
        self,
        consulta: str,
        contexto: dict[int, dict[str, Any]],
    ) -> dict[str, Any]:

        candidatos = (
            self._extrair_candidatos_informacao(
                contexto
            )
        )

        if not candidatos:

            return {
                "sucesso": False,
                "tipo": "contexto",
                "operacao": "selecionar",
                "valor": None,
                "origem": "contexto",
                "candidatos": [],
                "erro": (
                    "Nenhuma informação produzida "
                    "por etapas anteriores foi encontrada "
                    "no contexto."
                ),
            }

        avaliados = []

        for candidato in candidatos:

            score, evidencias = (
                self._pontuar_candidato(
                    consulta,
                    candidato,
                )
            )

            avaliados.append(
                {
                    **candidato,
                    "score": score,
                    "evidencias": evidencias,
                }
            )

        melhor_score = max(
            item["score"]
            for item in avaliados
        )

        if melhor_score <= 0:

            return {
                "sucesso": False,
                "tipo": "contexto",
                "operacao": "selecionar",
                "valor": None,
                "origem": "contexto",
                "candidatos": [
                    {
                        "etapa": item["etapa"],
                        "caminho": item["caminho"],
                        "tipo": item["tipo"],
                        "evidencias": item["evidencias"],
                    }
                    for item in avaliados
                ],
                "erro": (
                    "Nenhuma informação compatível "
                    "foi encontrada no contexto."
                ),
            }

        melhores = [
            item
            for item in avaliados
            if item["score"]
            == melhor_score
        ]

        # Mesma informação física pode aparecer duplicada
        # no contexto. Deduplicamos por representação exata.
        unicos: dict[str, dict[str, Any]] = {}

        for item in melhores:

            assinatura = item["texto"]

            if assinatura not in unicos:

                unicos[assinatura] = item

        melhores = list(
            unicos.values()
        )

        if len(melhores) != 1:

            return {
                "sucesso": False,
                "tipo": "contexto",
                "operacao": "selecionar",
                "valor": None,
                "origem": "contexto",
                "candidatos": [
                    {
                        "etapa": item["etapa"],
                        "caminho": item["caminho"],
                        "tipo": item["tipo"],
                        "score": item["score"],
                        "evidencias": item["evidencias"],
                    }
                    for item in melhores
                ],
                "erro": (
                    "A seleção é ambígua: "
                    "mais de uma informação do contexto "
                    "possui evidência equivalente."
                ),
            }

        escolhido = melhores[0]

        return {
            "sucesso": True,
            "tipo": "contexto",
            "operacao": "selecionar",
            "valor": escolhido["valor"],
            "origem": "contexto",
            "etapa_origem": escolhido["etapa"],
            "caminho_origem": escolhido["caminho"],
            "tipo_informacao": escolhido["tipo"],
            "evidencias": escolhido["evidencias"],
            "candidatos": [
                {
                    "etapa": item["etapa"],
                    "caminho": item["caminho"],
                    "tipo": item["tipo"],
                    "score": item["score"],
                    "evidencias": item["evidencias"],
                }
                for item in avaliados
            ],
            "erro": None,
        }

    # ============================================================
    # SELECIONAR
    # ============================================================

    def _executar_selecionar(
        self,
        argumentos: dict[str, Any],
        contexto: dict[int, dict[str, Any]],
    ) -> dict[str, Any]:

        consulta = argumentos.get(
            "consulta"
        )

        if not isinstance(
            consulta,
            str,
        ):

            return {
                "sucesso": False,
                "tipo": "contexto",
                "operacao": "selecionar",
                "valor": None,
                "erro": (
                    "O argumento 'consulta' "
                    "precisa ser uma string."
                ),
            }

        consulta = consulta.strip()

        if not consulta:

            return {
                "sucesso": False,
                "tipo": "contexto",
                "operacao": "selecionar",
                "valor": None,
                "erro": (
                    "A consulta de seleção "
                    "não pode ser vazia."
                ),
            }

        resultado_arquivo = (
            self._selecionar_arquivo_explicitamente(
                consulta,
                contexto,
            )
        )

        if resultado_arquivo is not None:
            return resultado_arquivo

        return (
            self._executar_selecionar_informacao(
                consulta,
                contexto,
            )
        )

    # ============================================================
    # EXECUÇÃO GENÉRICA
    # ============================================================

    def executar(
        self,
        nome: str,
        argumentos: dict[str, Any],
        contexto: dict[int, dict[str, Any]],
    ) -> dict[str, Any]:

        especificacao = (
            self.registro.obter_especificacao(
                nome
            )
        )

        if especificacao is None:

            return {
                "sucesso": False,
                "tipo": "contexto",
                "operacao": nome,
                "valor": None,
                "erro": (
                    f"Operação de contexto "
                    f"'{nome}' não existe."
                ),
            }

        validacao = (
            self.registro.validar_argumentos(
                nome,
                argumentos,
            )
        )

        if not validacao["valido"]:

            return {
                "sucesso": False,
                "tipo": "contexto",
                "operacao": nome,
                "valor": None,
                "erro": validacao[
                    "erro"
                ],
            }

        implementacao = (
            self.implementacoes.get(
                nome
            )
        )

        if implementacao is None:

            return {
                "sucesso": False,
                "tipo": "contexto",
                "operacao": nome,
                "valor": None,
                "erro": (
                    f"A operação '{nome}' "
                    "está registrada, mas ainda "
                    "não possui implementação."
                ),
            }

        return implementacao(
            argumentos,
            contexto,
        )


# ================================================================
# MAIN
# ================================================================

def main() -> None:

