def listar_gpus_reais():

    gpus = []

    caminhos = sorted(
        glob.glob(
            "/sys/class/drm/card[0-9]*"
        )
    )

    padrao = re.compile(
        r"^card[0-9]+$"
    )

    for caminho in caminhos:

        nome = os.path.basename(
            caminho
        )

        if not padrao.match(nome):
            continue

        device = os.path.join(
            caminho,
            "device",
        )

        vendor = ler_texto(
            os.path.join(
                device,
                "vendor",
            )
        )

        if vendor is None:
            continue

        eventos = ler_uevent(
            os.path.join(
                device,
                "uevent",
            )
        )

        uso = ler_inteiro(
            os.path.join(
                device,
                "gpu_busy_percent",
            )
        )

        temperaturas = (
            ler_temperaturas_gpu(
                device
            )
        )

        gpus.append(
            {
                "dispositivo": nome,

                "identidade": {
                    "vendor": vendor,

                    "driver": eventos.get(
                        "DRIVER"
                    ),

                    "pci_id": eventos.get(
                        "PCI_ID"
                    ),

                    "pci_subsys_id": (
                        eventos.get(
                            "PCI_SUBSYS_ID"
                        )
                    ),

                    "pci_slot": (
                        eventos.get(
                            "PCI_SLOT_NAME"
                        )
                    ),
                },

                "uso_percentual": uso,

                "estado_uso": (
                    classificar_gpu(
                        uso
                    )
                ),

                "temperaturas": (
                    temperaturas
                ),
            }
        )

    return gpus


def classificar_gpu(
    uso,
):

    if uso is None:
        return "indisponivel"

    if uso < 20:
        return "baixa_carga"

    if uso < 60:
        return "carga_moderada"

    if uso < 85:
        return "carga_alta"

    return "carga_muito_alta"


