# PERCEPÇÃO CORPORAL
# ============================================================

def perceber_corpo(
    cpu_anterior=None,
):

    cpu_atual = ler_cpu()

    uso_cpu = (
        calcular_uso_cpu(
            cpu_anterior,
            cpu_atual,
        )
        if cpu_anterior is not None
        else None
    )

    estado = {
        "identidade": {
            "nome": NOME,
        },

        "corpo": {
            "cpu": {
                "uso_percentual": uso_cpu,

                "estado": (
                    classificar_cpu(
                        uso_cpu
                    )
                ),

                "calibrada": (
                    uso_cpu is not None
                ),
            },

            "memoria": ler_memoria(),

            "temperaturas_gerais": (
                ler_temperaturas()
            ),

            "gpu": (
                listar_gpus_reais()
            ),

            "armazenamento": (
                ler_armazenamento()
            ),

            "processos": (
                contar_processos()
            ),

            "uptime_segundos": (
                ler_uptime()
            ),
        },

        "percepcao": {
            "timestamp": agora_iso(),
        },
    }

    return (
        estado,
        cpu_atual,
    )


# ============================================================
# COMPARAÇÃO DE ESTADOS
# ============================================================

def comparar_valor(
    caminho,
    anterior,
    atual,
    mudancas,
):

    if anterior == atual:
        return

    mudancas.append(
        {
            "caminho": caminho,
            "anterior": anterior,
            "atual": atual,
        }
    )


def comparar_estados(
    anterior,
    atual,
):

    mudancas = []

    if anterior is None:

        return [
            {
                "tipo": "primeira_percepcao",
                "caminho": "corpo",
                "anterior": None,
                "atual": "observado",
            }
        ]

    corpo_anterior = anterior.get(
        "corpo",
        {}
    )

    corpo_atual = atual.get(
        "corpo",
        {}
    )

    # --------------------------------------------------------
    # CPU
    # --------------------------------------------------------

    cpu_anterior = (
        corpo_anterior.get(
            "cpu",
            {}
        )
    )

    cpu_atual = (
        corpo_atual.get(
            "cpu",
            {}
        )
    )

    comparar_valor(
        "cpu.estado",
        cpu_anterior.get(
            "estado"
        ),
        cpu_atual.get(
            "estado"
        ),
        mudancas,
    )

    comparar_valor(
        "cpu.uso_percentual",
        cpu_anterior.get(
            "uso_percentual"
        ),
        cpu_atual.get(
            "uso_percentual"
        ),
        mudancas,
    )

    # --------------------------------------------------------
    # MEMÓRIA
    # --------------------------------------------------------

    memoria_anterior = (
        corpo_anterior.get(
            "memoria"
        )
        or {}
    )

    memoria_atual = (
        corpo_atual.get(
            "memoria"
        )
        or {}
    )

    comparar_valor(
        "memoria.estado",
        memoria_anterior.get(
            "estado"
        ),
        memoria_atual.get(
            "estado"
        ),
        mudancas,
    )

    comparar_valor(
        "memoria.uso_percentual",
        memoria_anterior.get(
            "uso_percentual"
        ),
        memoria_atual.get(
            "uso_percentual"
        ),
        mudancas,
    )

    # --------------------------------------------------------
    # DISCO
    # --------------------------------------------------------

    armazenamento_anterior = (
        corpo_anterior.get(
            "armazenamento"
        )
        or {}
    )

    armazenamento_atual = (
        corpo_atual.get(
            "armazenamento"
        )
        or {}
    )

    comparar_valor(
        "armazenamento.estado",
        armazenamento_anterior.get(
            "estado"
        ),
        armazenamento_atual.get(
            "estado"
        ),
        mudancas,
    )

    # --------------------------------------------------------
    # GPU
    # --------------------------------------------------------

    gpus_anterior = (
        corpo_anterior.get(
            "gpu",
            []
        )
    )

    gpus_atual = (
        corpo_atual.get(
            "gpu",
            []
        )
    )

    if (
        gpus_anterior
        and gpus_atual
    ):

        gpu_anterior = (
            gpus_anterior[0]
        )

        gpu_atual = (
            gpus_atual[0]
        )

        comparar_valor(
            "gpu.estado_uso",
            gpu_anterior.get(
                "estado_uso"
            ),
            gpu_atual.get(
                "estado_uso"
            ),
            mudancas,
        )

        comparar_valor(
            "gpu.uso_percentual",
            gpu_anterior.get(
                "uso_percentual"
            ),
            gpu_atual.get(
                "uso_percentual"
            ),
            mudancas,
        )

        temperaturas_anterior = (
            gpu_anterior.get(
                "temperaturas",
                []
            )
        )

        temperaturas_atual = (
            gpu_atual.get(
                "temperaturas",
                []
            )
        )

        limite = min(
            len(
                temperaturas_anterior
            ),
            len(
                temperaturas_atual
            ),
        )

        for indice in range(
            limite
        ):

            antiga = (
                temperaturas_anterior[
                    indice
                ]
            )

            nova = (
                temperaturas_atual[
                    indice
                ]
            )

            comparar_valor(
                (
                    "gpu.temperaturas."
                    f"{indice}.estado"
                ),
                antiga.get(
                    "estado"
                ),
                nova.get(
                    "estado"
                ),
                mudancas,
            )

            comparar_valor(
                (
                    "gpu.temperaturas."
                    f"{indice}.temperatura_c"
                ),
                antiga.get(
                    "temperatura_c"
                ),
                nova.get(
                    "temperatura_c"
                ),
                mudancas,
            )

    return mudancas


