def agora_iso():
    return (
        datetime.now()
        .astimezone()
        .isoformat()
    )


# ============================================================
# LEITURA SEGURA
# ============================================================

def ler_texto(caminho):
    try:

        with open(
            caminho,
            "r",
            encoding="utf-8",
        ) as arquivo:

            return arquivo.read().strip()

    except (
        OSError,
        UnicodeDecodeError,
    ):

        return None


def ler_inteiro(caminho):

    valor = ler_texto(
        caminho
    )

    if valor is None:
        return None

    try:

        return int(
            valor
        )

    except ValueError:

        return None


# ============================================================
# CPU
# ============================================================

def ler_cpu():

    linhas = ler_texto(
        "/proc/stat"
    )

    if not linhas:
        return None

    for linha in linhas.splitlines():

        if not linha.startswith(
            "cpu "
        ):
            continue

        partes = linha.split()

        try:

            valores = [
                int(valor)
                for valor in partes[1:8]
            ]

        except ValueError:

            return None

        if len(valores) < 7:
            return None

        return valores

    return None


def calcular_uso_cpu(
    anterior,
    atual,
):

    if (
        anterior is None
        or atual is None
    ):
        return None

    total_anterior = sum(
        anterior
    )

    total_atual = sum(
        atual
    )

    idle_anterior = (
        anterior[3]
        + anterior[4]
    )

    idle_atual = (
        atual[3]
        + atual[4]
    )

    total_delta = (
        total_atual
        - total_anterior
    )

    idle_delta = (
        idle_atual
        - idle_anterior
    )

    if total_delta <= 0:
        return None

    uso = (
        1
        - (
            idle_delta
            / total_delta
        )
    ) * 100

    uso = max(
        0.0,
        min(
            100.0,
            uso,
        )
    )

    return round(
        uso,
        2,
    )


def classificar_cpu(
    uso,
):

    if uso is None:
        return "indisponivel"

    if uso < 20:
        return "baixa_carga"

    if uso < 60:
        return "carga_moderada"

    if uso < 85:
        return "carga_alta"

    return "carga_muito_alta"


# ============================================================
# MEMÓRIA
# ============================================================

def ler_memoria():

    texto = ler_texto(
        "/proc/meminfo"
    )

    if not texto:
        return None

    valores = {}

    for linha in texto.splitlines():

        partes = linha.split()

        if len(partes) < 2:
            continue

        chave = partes[0].rstrip(
            ":"
        )

        try:

            valor_kb = int(
                partes[1]
            )

        except ValueError:

            continue

        valores[
            chave
        ] = valor_kb

    total = valores.get(
        "MemTotal"
    )

    disponivel = valores.get(
        "MemAvailable"
    )

    if (
        total is None
        or disponivel is None
    ):
        return None

    usado = (
        total
        - disponivel
    )

    percentual = (
        usado
        / total
    ) * 100

    return {
        "total_gb": round(
            total
            / 1024
            / 1024,
            2,
        ),

        "disponivel_gb": round(
            disponivel
            / 1024
            / 1024,
            2,
        ),

        "usado_gb": round(
            usado
            / 1024
            / 1024,
            2,
        ),

        "uso_percentual": round(
            percentual,
            2,
        ),

        "estado": (
            classificar_memoria(
                percentual
            )
        ),
    }


def classificar_memoria(
    uso,
):

    if uso < 50:
        return "normal"

    if uso < 75:
        return "uso_moderado"

    if uso < 90:
        return "uso_alto"

    return "uso_muito_alto"


# ============================================================
# GPU — UEVENT
# ============================================================

def ler_uevent(
    caminho,
):

    texto = ler_texto(
        caminho
    )

    if not texto:
        return {}

    resultado = {}

    for linha in texto.splitlines():

        if "=" not in linha:
            continue

        chave, valor = (
            linha.split(
                "=",
                1,
            )
        )

        resultado[
            chave
        ] = valor

    return resultado


# ============================================================
# GPU — TEMPERATURAS
# ============================================================

def ler_temperaturas_gpu(
    device,
):

    temperaturas = []

    hwmon_base = os.path.join(
        device,
        "hwmon",
    )

    caminhos_hwmon = sorted(
        glob.glob(
            os.path.join(
                hwmon_base,
                "hwmon*",
            )
        )
    )

    for hwmon in caminhos_hwmon:

        nome_chip = ler_texto(
            os.path.join(
                hwmon,
                "name",
            )
        )

        sensores = sorted(
            glob.glob(
                os.path.join(
                    hwmon,
                    "temp*_input",
                )
            )
        )

        for entrada in sensores:

            valor = ler_inteiro(
                entrada
            )

            if valor is None:
                continue

            nome_sensor = os.path.basename(
                entrada
            )

            numero = nome_sensor[
                4:-6
            ]

            rotulo = ler_texto(
                os.path.join(
                    hwmon,
                    f"temp{numero}_label",
                )
            )

            temperatura = round(
                valor / 1000,
                2,
            )

            temperaturas.append(
                {
                    "sensor": nome_sensor,
                    "rotulo": rotulo,
                    "chip": nome_chip,
                    "temperatura_c": temperatura,
                    "estado": (
                        classificar_temperatura(
                            temperatura
                        )
                    ),
                }
            )

    return temperaturas


# ============================================================
# TEMPERATURA
# ============================================================

def classificar_temperatura(
    temperatura,
):

    if temperatura < 40:
        return "fria"

    if temperatura < 65:
        return "normal"

    if temperatura < 80:
        return "quente"

    return "muito_quente"


# ============================================================
# GPU
# ============================================================

def listar_gpus_reais():

    gpus = []

    caminhos = sorted(
        glob.glob(
            "/sys/class/drm/card[0-9]*"
        )
    )

    padrao = re.compile(
        r"^card[0-9]+$"
    )

    for caminho in caminhos:

        nome = os.path.basename(
            caminho
        )

        if not padrao.match(nome):
            continue

        device = os.path.join(
            caminho,
            "device",
        )

        vendor = ler_texto(
            os.path.join(
                device,
                "vendor",
            )
        )

        if vendor is None:
            continue

        eventos = ler_uevent(
            os.path.join(
                device,
                "uevent",
            )
        )

        uso = ler_inteiro(
            os.path.join(
                device,
                "gpu_busy_percent",
            )
        )

        temperaturas = (
            ler_temperaturas_gpu(
                device
            )
        )

        gpus.append(
            {
                "dispositivo": nome,

                "identidade": {
                    "vendor": vendor,

                    "driver": eventos.get(
                        "DRIVER"
                    ),

                    "pci_id": eventos.get(
                        "PCI_ID"
                    ),

                    "pci_subsys_id": (
                        eventos.get(
                            "PCI_SUBSYS_ID"
                        )
                    ),

                    "pci_slot": (
                        eventos.get(
                            "PCI_SLOT_NAME"
                        )
                    ),
                },

                "uso_percentual": uso,

                "estado_uso": (
                    classificar_gpu(
                        uso
                    )
                ),

                "temperaturas": (
                    temperaturas
                ),
            }
        )

    return gpus


def classificar_gpu(
    uso,
):

    if uso is None:
        return "indisponivel"

    if uso < 20:
        return "baixa_carga"

    if uso < 60:
        return "carga_moderada"

    if uso < 85:
        return "carga_alta"

    return "carga_muito_alta"


# ============================================================
# TEMPERATURAS GERAIS
# ============================================================

def ler_temperaturas():

    resultados = []

    caminhos = sorted(
        glob.glob(
            "/sys/class/thermal/"
            "thermal_zone[0-9]*"
        )
    )

    for caminho in caminhos:

        tipo = ler_texto(
            os.path.join(
                caminho,
                "type",
            )
        )

        valor = ler_inteiro(
            os.path.join(
                caminho,
                "temp",
            )
        )

        if (
            tipo is None
            or valor is None
        ):
            continue

        temperatura = round(
            valor / 1000,
            2,
        )

        resultados.append(
            {
                "zona": os.path.basename(
                    caminho.rstrip("/")
                ),

                "tipo": tipo,

                "temperatura_c": (
                    temperatura
                ),

                "estado": (
                    classificar_temperatura(
                        temperatura
                    )
                ),
            }
        )

    return resultados


# ============================================================
# ARMAZENAMENTO
# ============================================================

def ler_armazenamento():

    uso = shutil.disk_usage(
        "/"
    )

    total = uso.total

    usado = uso.used

    livre = uso.free

    percentual = (
        usado
        / total
    ) * 100

    return {
        "ponto": "/",

        "total_gb": round(
            total
            / 1024
            / 1024
            / 1024,
            2,
        ),

        "usado_gb": round(
            usado
            / 1024
            / 1024
            / 1024,
            2,
        ),

        "livre_gb": round(
            livre
            / 1024
            / 1024
            / 1024,
            2,
        ),

        "uso_percentual": round(
            percentual,
            2,
        ),

        "estado": (
            classificar_armazenamento(
                percentual
            )
        ),
    }


def classificar_armazenamento(
    uso,
):

    if uso < 70:
        return "normal"

    if uso < 85:
        return "ocupado"

    if uso < 95:
        return "muito_ocupado"

    return "critico"


# ============================================================
# PROCESSOS
# ============================================================

def contar_processos():

    processos = glob.glob(
        "/proc/[0-9]*"
    )

    total = 0

    for caminho in processos:

        nome = os.path.basename(
            caminho
        )

        if nome.isdigit():
            total += 1

    return total


# ============================================================
# UPTIME
# ============================================================

def ler_uptime():

    texto = ler_texto(
        "/proc/uptime"
    )

    if not texto:
        return None

    try:

        return round(
            float(
                texto.split()[0]
            ),
            2,
        )

    except (
        ValueError,
        IndexError,
    ):

        return None


# ============================================================
# PERCEPÇÃO CORPORAL
# ============================================================

def perceber_corpo(
    cpu_anterior=None,
):

    cpu_atual = ler_cpu()

    uso_cpu = (
        calcular_uso_cpu(
            cpu_anterior,
            cpu_atual,
        )
        if cpu_anterior is not None
        else None
    )

    estado = {
        "identidade": {
            "nome": NOME,
        },

        "corpo": {
            "cpu": {
                "uso_percentual": uso_cpu,

                "estado": (
                    classificar_cpu(
                        uso_cpu
                    )
                ),

                "calibrada": (
                    uso_cpu is not None
                ),
            },

            "memoria": ler_memoria(),

            "temperaturas_gerais": (
                ler_temperaturas()
            ),

            "gpu": (
                listar_gpus_reais()
            ),

            "armazenamento": (
                ler_armazenamento()
            ),

            "processos": (
                contar_processos()
            ),

            "uptime_segundos": (
                ler_uptime()
            ),
        },

        "percepcao": {
            "timestamp": agora_iso(),
        },
    }

    return (
        estado,
        cpu_atual,
    )


# ============================================================
# COMPARAÇÃO DE ESTADOS
# ============================================================

def comparar_valor(
    caminho,
    anterior,
    atual,
    mudancas,
):

    if anterior == atual:
        return

    mudancas.append(
        {
            "caminho": caminho,
            "anterior": anterior,
            "atual": atual,
        }
    )


def comparar_estados(
    anterior,
    atual,
):

    mudancas = []

    if anterior is None:

        return [
            {
                "tipo": "primeira_percepcao",
                "caminho": "corpo",
                "anterior": None,
                "atual": "observado",
            }
        ]

    corpo_anterior = anterior.get(
        "corpo",
        {}
    )

    corpo_atual = atual.get(
        "corpo",
        {}
    )

    # --------------------------------------------------------
    # CPU
    # --------------------------------------------------------

    cpu_anterior = (
        corpo_anterior.get(
            "cpu",
            {}
        )
    )

    cpu_atual = (
        corpo_atual.get(
            "cpu",
            {}
        )
    )

    comparar_valor(
        "cpu.estado",
        cpu_anterior.get(
            "estado"
        ),
        cpu_atual.get(
            "estado"
        ),
        mudancas,
    )

    comparar_valor(
        "cpu.uso_percentual",
        cpu_anterior.get(
            "uso_percentual"
        ),
        cpu_atual.get(
            "uso_percentual"
        ),
        mudancas,
    )

    # --------------------------------------------------------
    # MEMÓRIA
    # --------------------------------------------------------

    memoria_anterior = (
        corpo_anterior.get(
            "memoria"
        )
        or {}
    )

    memoria_atual = (
        corpo_atual.get(
            "memoria"
        )
        or {}
    )

    comparar_valor(
        "memoria.estado",
        memoria_anterior.get(
            "estado"
        ),
        memoria_atual.get(
            "estado"
        ),
        mudancas,
    )

    comparar_valor(
        "memoria.uso_percentual",
        memoria_anterior.get(
            "uso_percentual"
        ),
        memoria_atual.get(
            "uso_percentual"
        ),
        mudancas,
    )

    # --------------------------------------------------------
    # DISCO
    # --------------------------------------------------------

    armazenamento_anterior = (
        corpo_anterior.get(
            "armazenamento"
        )
        or {}
    )

    armazenamento_atual = (
        corpo_atual.get(
            "armazenamento"
        )
        or {}
    )

    comparar_valor(
        "armazenamento.estado",
        armazenamento_anterior.get(
            "estado"
        ),
        armazenamento_atual.get(
            "estado"
        ),
        mudancas,
    )

    # --------------------------------------------------------
    # GPU
    # --------------------------------------------------------

    gpus_anterior = (
        corpo_anterior.get(
            "gpu",
            []
        )
    )

    gpus_atual = (
        corpo_atual.get(
            "gpu",
            []
        )
    )

    if (
        gpus_anterior
        and gpus_atual
    ):

        gpu_anterior = (
            gpus_anterior[0]
        )

        gpu_atual = (
            gpus_atual[0]
        )

        comparar_valor(
            "gpu.estado_uso",
            gpu_anterior.get(
                "estado_uso"
            ),
            gpu_atual.get(
                "estado_uso"
            ),
            mudancas,
        )

        comparar_valor(
            "gpu.uso_percentual",
            gpu_anterior.get(
                "uso_percentual"
            ),
            gpu_atual.get(
                "uso_percentual"
            ),
            mudancas,
        )

        temperaturas_anterior = (
            gpu_anterior.get(
                "temperaturas",
                []
            )
        )

        temperaturas_atual = (
            gpu_atual.get(
                "temperaturas",
                []
            )
        )

        limite = min(
            len(
                temperaturas_anterior
            ),
            len(
                temperaturas_atual
            ),
        )

        for indice in range(
            limite
        ):

            antiga = (
                temperaturas_anterior[
                    indice
                ]
            )

            nova = (
                temperaturas_atual[
                    indice
                ]
            )

            comparar_valor(
                (
                    "gpu.temperaturas."
                    f"{indice}.estado"
                ),
                antiga.get(
                    "estado"
                ),
                nova.get(
                    "estado"
                ),
                mudancas,
            )

            comparar_valor(
                (
                    "gpu.temperaturas."
                    f"{indice}.temperatura_c"
                ),
                antiga.get(
                    "temperatura_c"
                ),
                nova.get(
                    "temperatura_c"
                ),
                mudancas,
            )

    return mudancas


