def criar_evento(
    caminho,
    anterior,
    atual,
    motivo,
):

    return {
        "timestamp": agora_iso(),

        "tipo": "mudanca_corporal",

        "caminho": caminho,

        "anterior": anterior,

        "atual": atual,

        "delta": round(
            atual - anterior,
            2,
        ),

        "motivo": motivo,
    }


def detectar_eventos_significativos(
    estado_anterior,
    estado_atual,
):

    eventos = []

    if (
        estado_anterior is None
        or estado_atual is None
    ):
        return eventos

    corpo_anterior = (
        estado_anterior.get(
            "corpo",
            {}
        )
    )

    corpo_atual = (
        estado_atual.get(
            "corpo",
            {}
        )
    )

    # --------------------------------------------------------
    # CPU
    # --------------------------------------------------------

    cpu_anterior = (
        corpo_anterior.get(
            "cpu",
            {}
        )
        or {}
    )

    cpu_atual = (
        corpo_atual.get(
            "cpu",
            {}
        )
        or {}
    )

    valor_anterior = (
        cpu_anterior.get(
            "uso_percentual"
        )
    )

    valor_atual = (
        cpu_atual.get(
            "uso_percentual"
        )
    )

    if (
        isinstance(
            valor_anterior,
            (int, float),
        )
        and
        isinstance(
            valor_atual,
            (int, float),
        )
    ):

        delta = abs(
            valor_atual
            - valor_anterior
        )

        if delta >= LIMITE_CPU:

            direcao = (
                "aumento"
                if valor_atual > valor_anterior
                else "redução"
            )

            eventos.append(
                criar_evento(
                    "cpu.uso_percentual",
                    valor_anterior,
                    valor_atual,
