            detectar_eventos_significativos(
                estado_anterior,
                estado_atual,
            )
        )

        # ----------------------------------------------------
        # MEMÓRIA
        # ----------------------------------------------------

        memoria[
            "sessao"
        ][
            "ciclos"
        ] += 1

        if eventos:

            memoria[
                "sessao"
            ][
                "eventos"
            ].extend(
                eventos
            )

            memoria[
                "sessao"
            ][
                "eventos"
            ] = memoria[
                "sessao"
            ][
                "eventos"
            ][-MAX_EVENTOS:]

        # ----------------------------------------------------
        # PERSISTÊNCIA
        # ----------------------------------------------------

        salvar_estado_corpo(
            estado_atual
        )

        salvar_memoria_corporal(
            memoria
        )

        # ----------------------------------------------------
        # EXIBIÇÃO
        # ----------------------------------------------------

        mostrar_percepcao(
            estado_atual,
            mudancas,
            eventos,
        )

        # ----------------------------------------------------
        # PREPARAR PRÓXIMO CICLO
        # ----------------------------------------------------

        estado_anterior = (
            estado_atual
        )

        cpu_anterior = cpu_atual

        time.sleep(
            INTERVALO_CICLO
        )


