def ler_temperaturas():

    resultados = []

    caminhos = sorted(
        glob.glob(
            "/sys/class/thermal/"
            "thermal_zone[0-9]*"
        )
    )

    for caminho in caminhos:

        tipo = ler_texto(
            os.path.join(
                caminho,
                "type",
            )
        )

        valor = ler_inteiro(
            os.path.join(
