# ARMAZENAMENTO
# ============================================================

def ler_armazenamento():

    uso = shutil.disk_usage(
        "/"
    )

    total = uso.total

    usado = uso.used

    livre = uso.free

    percentual = (
        usado
        / total
    ) * 100

    return {
        "ponto": "/",

        "total_gb": round(
            total
            / 1024
            / 1024
            / 1024,
            2,
        ),

        "usado_gb": round(
            usado
            / 1024
            / 1024
            / 1024,
            2,
        ),

        "livre_gb": round(
            livre
            / 1024
            / 1024
            / 1024,
            2,
        ),

        "uso_percentual": round(
            percentual,
            2,
        ),

        "estado": (
            classificar_armazenamento(
                percentual
            )
        ),
    }


def classificar_armazenamento(
    uso,
):

    if uso < 70:
        return "normal"

    if uso < 85:
        return "ocupado"

    if uso < 95:
        return "muito_ocupado"

    return "critico"


# ============================================================
# PROCESSOS
# ============================================================

def contar_processos():

    processos = glob.glob(
        "/proc/[0-9]*"
    )

    total = 0

    for caminho in processos:

        nome = os.path.basename(
            caminho
        )

        if nome.isdigit():
            total += 1

    return total


