# UPTIME
# ============================================================

def ler_uptime():

    texto = ler_texto(
        "/proc/uptime"
    )

    if not texto:
        return None

    try:

        return round(
            float(
                texto.split()[0]
            ),
            2,
        )

    except (
        ValueError,
        IndexError,
    ):

        return None


# ============================================================
# PERCEPÇÃO CORPORAL
# ============================================================

def perceber_corpo(
    cpu_anterior=None,
):

    cpu_atual = ler_cpu()

    uso_cpu = (
        calcular_uso_cpu(
            cpu_anterior,
            cpu_atual,
        )
        if cpu_anterior is not None
        else None
    )

    estado = {
        "identidade": {
            "nome": NOME,
        },

        "corpo": {
            "cpu": {
                "uso_percentual": uso_cpu,

                "estado": (
                    classificar_cpu(
                        uso_cpu
                    )
                ),

                "calibrada": (
                    uso_cpu is not None
                ),
            },

            "memoria": ler_memoria(),

            "temperaturas_gerais": (
                ler_temperaturas()
            ),

