            )

            valor_atual = nova.get(
                "temperatura_c"
            )

            if not (
                isinstance(
                    valor_anterior,
                    (int, float),
                )
                and
                isinstance(
                    valor_atual,
                    (int, float),
                )
            ):
                continue

            delta = abs(
                valor_atual
                - valor_anterior
            )

            if delta >= LIMITE_TEMPERATURA:

                rotulo = (
                    nova.get(
                        "rotulo"
                    )
                    or nova.get(
                        "sensor"
                    )
                    or f"sensor_{indice}"
                )

                direcao = (
                    "aumento"
                    if valor_atual
                    > valor_anterior
                    else "redução"
                )

                eventos.append(
                    criar_evento(
                        (
                            "gpu.temperaturas."
                            f"{rotulo}"
                        ),
                        valor_anterior,
                        valor_atual,
                        (
                            f"mudança significativa "
                            f"de temperatura ({direcao})"
                        ),
                    )
                )

    return eventos


# ============================================================
# MEMÓRIA CORPORAL
# ============================================================

def carregar_memoria_corporal():

    if not os.path.exists(
        ARQUIVO_MEMORIA_CORPORAL
    ):
        return {
            "identidade": {
                "nome": NOME
            },

            "sessao": {
                "iniciada_em": agora_iso(),

                "ciclos": 0,

                "eventos": [],
            },
        }

    try:

        with open(
            ARQUIVO_MEMORIA_CORPORAL,
            "r",
            encoding="utf-8",
        ) as arquivo:

            memoria = json.load(
                arquivo
            )

        if not isinstance(
            memoria,
            dict,
        ):
            raise ValueError

        memoria.setdefault(
            "identidade",
            {
                "nome": NOME
            },
        )

        memoria.setdefault(
            "sessao",
            {},
        )

        memoria[
            "sessao"
        ].setdefault(
            "ciclos",
            0,
        )

        memoria[
            "sessao"
        ].setdefault(
            "eventos",
            [],
        )

        return memoria

    except (
        OSError,
        json.JSONDecodeError,
        ValueError,
    ):

        return {
            "identidade": {
                "nome": NOME
            },

            "sessao": {
                "iniciada_em": agora_iso(),

                "ciclos": 0,

                "eventos": [],
            },
        }


def salvar_memoria_corporal(
    memoria,
):

    temporario = (
        ARQUIVO_MEMORIA_CORPORAL
        + ".tmp"
    )

    with open(
        temporario,
        "w",
        encoding="utf-8",
    ) as arquivo:

        json.dump(
            memoria,
            arquivo,
            ensure_ascii=False,
            indent=2,
        )

    os.replace(
        temporario,
        ARQUIVO_MEMORIA_CORPORAL,
    )


