            estado,
            arquivo,
            ensure_ascii=False,
            indent=2,
        )

    os.replace(
        temporario,
        ARQUIVO_ESTADO_CORPO,
    )


# ============================================================
# EXIBIÇÃO
# ============================================================

def mostrar_percepcao(
    estado,
    mudancas,
    eventos,
):

    corpo = estado[
        "corpo"
    ]

    print(
        "----------------------------------------------"
    )

    print(
        f"[Nixal] percepção "
        f"{estado['percepcao']['timestamp']}"
    )

    # --------------------------------------------------------
    # CPU
    # --------------------------------------------------------

    cpu = corpo[
        "cpu"
    ]

    if not cpu[
        "calibrada"
    ]:

        print(
            "CPU: calibrando..."
        )

    else:

        print(
            f"CPU: "
            f"{cpu['uso_percentual']:.2f}% "
            f"| estado="
            f"{cpu['estado']}"
        )

    # --------------------------------------------------------
    # RAM
    # --------------------------------------------------------

    memoria = corpo[
        "memoria"
    ]

    if memoria is None:

        print(
            "RAM: indisponível"
        )

    else:

        print(
            f"RAM: "
            f"{memoria['uso_percentual']:.2f}% "
            f"("
            f"{memoria['usado_gb']:.2f}/"
            f"{memoria['total_gb']:.2f} GB"
            f") "
            f"| estado="
            f"{memoria['estado']}"
        )

    # --------------------------------------------------------
    # TEMPERATURAS
    # --------------------------------------------------------

    temperaturas = corpo[
        "temperaturas_gerais"
    ]

    if temperaturas:

        for temperatura in temperaturas:

            print(
                f"Temperatura "
                f"{temperatura['tipo']}: "
                f"{temperatura['temperatura_c']:.2f}°C "
                f"| estado="
                f"{temperatura['estado']}"
            )

    else:

        print(
            "Temperaturas gerais: "
            "nenhuma zona detectada"
        )

    # --------------------------------------------------------
    # GPU
    # --------------------------------------------------------

    gpus = corpo[
        "gpu"
    ]

    if gpus:

        for gpu in gpus:

            identidade = gpu[
                "identidade"
            ]

            print(
                f"GPU real: "
                f"{gpu['dispositivo']} "
                f"| vendor="
                f"{identidade['vendor']} "
                f"| uso="
                f"{gpu['uso_percentual']} "
                f"| estado="
                f"{gpu['estado_uso']}"
            )

            print(
                f"  driver: "
                f"{identidade['driver']}"
            )

            print(
                f"  pci_id: "
                f"{identidade['pci_id']}"
            )

            print(
                f"  slot: "
                f"{identidade['pci_slot']}"
            )

            for sensor in gpu[
                "temperaturas"
            ]:

                rotulo = (
                    sensor["rotulo"]
                    or sensor["sensor"]
                )

                print(
                    f"  {rotulo}: "
                    f"{sensor['temperatura_c']:.2f}°C "
                    f"| estado="
                    f"{sensor['estado']}"
                )

    else:

        print(
            "GPU real: nenhuma detectada"
        )

    # --------------------------------------------------------
    # DISCO
    # --------------------------------------------------------

    armazenamento = corpo[
        "armazenamento"
    ]

    print(
        f"Disco /: "
        f"{armazenamento['uso_percentual']:.2f}% "
        f"usado "
        f"| estado="
        f"{armazenamento['estado']}"
    )

    print(
        f"Processos: "
        f"{corpo['processos']}"
    )

    print(
        f"Uptime: "
        f"{corpo['uptime_segundos']} s"
    )

    # --------------------------------------------------------
    # MUDANÇAS
    # --------------------------------------------------------

    if mudancas:

        print(
            "Mudanças observadas:"
        )

        for mudanca in mudancas:

            print(
                f"  {mudanca['caminho']}: "
                f"{mudanca['anterior']} "
                f"-> "
                f"{mudanca['atual']}"
            )

    else:

        print(
            "Mudanças observadas: nenhuma"
        )

    # --------------------------------------------------------
    # EVENTOS SIGNIFICATIVOS
    # --------------------------------------------------------

    if eventos:

        print(
            "EVENTOS CORPORAIS:"
        )

        for evento in eventos:

            print(
                f"  {evento['caminho']}: "
                f"{evento['anterior']} "
                f"-> "
                f"{evento['atual']} "
                f"({evento['motivo']})"
            )

    else:

        print(
            "Eventos corporais: nenhum"
        )


# ============================================================
# PRINCIPAL
# ============================================================

def main():

    print()
    print(
        "=============================================="
    )
    print(
        "NIXAL"
    )
    print(
        "MICROETAPA 52.3 — MEMÓRIA CORPORAL"
    )
    print(
        "=============================================="
    )
    print()

    print(
        "Modo: SOMENTE LEITURA"
    )

    print(
        "Controle de hardware: DESATIVADO"
    )

    print(
        "Comparação temporal: ATIVADA"
    )

    print(
        "Eventos corporais: ATIVADOS"
    )

    print()

    # --------------------------------------------------------
    # IMPORTANTE
    #
    # O estado persistente anterior NÃO será usado como
    # comparação temporal da nova sessão.
    #
    # A sessão começa com uma nova linha de base.
    # --------------------------------------------------------

    cpu_anterior = None

    estado_anterior = None

    memoria = (
        carregar_memoria_corporal()
    )

    memoria[
        "sessao"
    ] = {
        "iniciada_em": agora_iso(),

        "ciclos": 0,

        "eventos": [],
    }

    while True:

        estado_atual, cpu_atual = (
            perceber_corpo(
                cpu_anterior
            )
        )

        # ----------------------------------------------------
        # COMPARAÇÃO
        # ----------------------------------------------------

        mudancas = comparar_estados(
            estado_anterior,
            estado_atual,
        )

        # ----------------------------------------------------
        # EVENTOS
        # ----------------------------------------------------

        eventos = (
            detectar_eventos_significativos(
                estado_anterior,
                estado_atual,
            )
        )

        # ----------------------------------------------------
        # MEMÓRIA
        # ----------------------------------------------------

        memoria[
            "sessao"
        ][
            "ciclos"
        ] += 1

        if eventos:

            memoria[
                "sessao"
            ][
                "eventos"
            ].extend(
                eventos
            )

            memoria[
                "sessao"
            ][
                "eventos"
            ] = memoria[
                "sessao"
            ][
                "eventos"
            ][-MAX_EVENTOS:]

        # ----------------------------------------------------
        # PERSISTÊNCIA
        # ----------------------------------------------------

        salvar_estado_corpo(
            estado_atual
        )

        salvar_memoria_corporal(
            memoria
        )

        # ----------------------------------------------------
        # EXIBIÇÃO
        # ----------------------------------------------------

        mostrar_percepcao(
            estado_atual,
            mudancas,
            eventos,
        )

        # ----------------------------------------------------
        # PREPARAR PRÓXIMO CICLO
        # ----------------------------------------------------

        estado_anterior = (
            estado_atual
        )

        cpu_anterior = cpu_atual

        time.sleep(
            INTERVALO_CICLO
        )


if __name__ == "__main__":

    try:

        main()

    except KeyboardInterrupt:

        print()
        print(
