    )

    total = uso.total

    usado = uso.used

    livre = uso.free

    percentual = (
        usado
        / total
    ) * 100

    return {
        "ponto": "/",

        "total_gb": round(
            total
            / 1024
            / 1024
            / 1024,
            2,
        ),

        "usado_gb": round(
