# ============================================================
# PROCESSOS
# ============================================================

def contar_processos():

    processos = glob.glob(
        "/proc/[0-9]*"
    )

    total = 0

    for caminho in processos:

        nome = os.path.basename(
            caminho
        )

        if nome.isdigit():
            total += 1

    return total


# ============================================================
# UPTIME
# ============================================================

def ler_uptime():

    texto = ler_texto(
        "/proc/uptime"
    )

    if not texto:
        return None

    try:

        return round(
            float(
                texto.split()[0]
            ),
            2,
        )

    except (
        ValueError,
        IndexError,
    ):

        return None


# ============================================================
# PERCEPÇÃO CORPORAL
# ============================================================

def perceber_corpo(
    cpu_anterior=None,
):

    cpu_atual = ler_cpu()

    uso_cpu = (
        calcular_uso_cpu(
            cpu_anterior,
            cpu_atual,
        )
        if cpu_anterior is not None
        else None
    )

    estado = {
        "identidade": {
            "nome": NOME,
        },

        "corpo": {
            "cpu": {
                "uso_percentual": uso_cpu,

                "estado": (
                    classificar_cpu(
                        uso_cpu
                    )
                ),

                "calibrada": (
                    uso_cpu is not None
                ),
            },

            "memoria": ler_memoria(),

            "temperaturas_gerais": (
                ler_temperaturas()
            ),

            "gpu": (
                listar_gpus_reais()
            ),

            "armazenamento": (
                ler_armazenamento()
            ),

            "processos": (
                contar_processos()
            ),

            "uptime_segundos": (
                ler_uptime()
            ),
        },

        "percepcao": {
            "timestamp": agora_iso(),
        },
    }

    return (
        estado,
        cpu_atual,
    )


# ============================================================
# COMPARAÇÃO DE ESTADOS
# ============================================================

def comparar_valor(
    caminho,
    anterior,
    atual,
    mudancas,
):

    if anterior == atual:
        return

    mudancas.append(
        {
            "caminho": caminho,
            "anterior": anterior,
            "atual": atual,
        }
    )


def comparar_estados(
    anterior,
    atual,
):

    mudancas = []

    if anterior is None:

        return [
            {
                "tipo": "primeira_percepcao",
                "caminho": "corpo",
                "anterior": None,
                "atual": "observado",
            }
        ]

    corpo_anterior = anterior.get(
        "corpo",
        {}
    )

    corpo_atual = atual.get(
        "corpo",
        {}
    )

    # --------------------------------------------------------
    # CPU
    # --------------------------------------------------------

    cpu_anterior = (
        corpo_anterior.get(
            "cpu",
            {}
        )
    )

    cpu_atual = (
        corpo_atual.get(
            "cpu",
            {}
        )
    )

    comparar_valor(
        "cpu.estado",
        cpu_anterior.get(
            "estado"
        ),
        cpu_atual.get(
            "estado"
        ),
        mudancas,
    )

    comparar_valor(
        "cpu.uso_percentual",
        cpu_anterior.get(
            "uso_percentual"
        ),
        cpu_atual.get(
            "uso_percentual"
        ),
        mudancas,
    )

    # --------------------------------------------------------
    # MEMÓRIA
    # --------------------------------------------------------

    memoria_anterior = (
        corpo_anterior.get(
            "memoria"
        )
        or {}
    )

    memoria_atual = (
        corpo_atual.get(
            "memoria"
        )
        or {}
    )

    comparar_valor(
        "memoria.estado",
        memoria_anterior.get(
            "estado"
        ),
        memoria_atual.get(
            "estado"
        ),
        mudancas,
    )

    comparar_valor(
        "memoria.uso_percentual",
        memoria_anterior.get(
            "uso_percentual"
        ),
        memoria_atual.get(
            "uso_percentual"
        ),
        mudancas,
    )

    # --------------------------------------------------------
    # DISCO
    # --------------------------------------------------------

    armazenamento_anterior = (
        corpo_anterior.get(
            "armazenamento"
        )
        or {}
    )

    armazenamento_atual = (
        corpo_atual.get(
            "armazenamento"
        )
        or {}
    )

    comparar_valor(
        "armazenamento.estado",
        armazenamento_anterior.get(
            "estado"
        ),
        armazenamento_atual.get(
            "estado"
        ),
        mudancas,
    )

    # --------------------------------------------------------
    # GPU
    # --------------------------------------------------------

    gpus_anterior = (
        corpo_anterior.get(
            "gpu",
            []
        )
    )

    gpus_atual = (
        corpo_atual.get(
            "gpu",
            []
        )
    )

    if (
        gpus_anterior
        and gpus_atual
    ):

        gpu_anterior = (
            gpus_anterior[0]
        )

        gpu_atual = (
            gpus_atual[0]
        )

        comparar_valor(
            "gpu.estado_uso",
            gpu_anterior.get(
                "estado_uso"
            ),
            gpu_atual.get(
                "estado_uso"
            ),
            mudancas,
        )

        comparar_valor(
            "gpu.uso_percentual",
            gpu_anterior.get(
                "uso_percentual"
            ),
            gpu_atual.get(
                "uso_percentual"
            ),
            mudancas,
        )

        temperaturas_anterior = (
            gpu_anterior.get(
                "temperaturas",
                []
            )
        )

        temperaturas_atual = (
            gpu_atual.get(
                "temperaturas",
                []
            )
        )

        limite = min(
            len(
                temperaturas_anterior
            ),
            len(
                temperaturas_atual
            ),
        )

        for indice in range(
            limite
        ):

            antiga = (
                temperaturas_anterior[
                    indice
                ]
            )

            nova = (
                temperaturas_atual[
                    indice
                ]
            )

            comparar_valor(
                (
                    "gpu.temperaturas."
                    f"{indice}.estado"
                ),
                antiga.get(
                    "estado"
                ),
                nova.get(
                    "estado"
                ),
                mudancas,
            )

            comparar_valor(
                (
                    "gpu.temperaturas."
                    f"{indice}.temperatura_c"
                ),
                antiga.get(
                    "temperatura_c"
                ),
                nova.get(
                    "temperatura_c"
                ),
                mudancas,
            )

    return mudancas


# ============================================================
# EVENTOS SIGNIFICATIVOS
# ============================================================

def criar_evento(
    caminho,
    anterior,
    atual,
    motivo,
):

    return {
        "timestamp": agora_iso(),

        "tipo": "mudanca_corporal",

        "caminho": caminho,

        "anterior": anterior,

        "atual": atual,

        "delta": round(
            atual - anterior,
            2,
        ),

        "motivo": motivo,
    }


def detectar_eventos_significativos(
    estado_anterior,
    estado_atual,
):

    eventos = []

    if (
        estado_anterior is None
        or estado_atual is None
    ):
        return eventos

    corpo_anterior = (
        estado_anterior.get(
            "corpo",
            {}
        )
    )

    corpo_atual = (
        estado_atual.get(
            "corpo",
            {}
        )
    )

    # --------------------------------------------------------
    # CPU
    # --------------------------------------------------------

    cpu_anterior = (
        corpo_anterior.get(
            "cpu",
            {}
        )
        or {}
    )

    cpu_atual = (
        corpo_atual.get(
            "cpu",
            {}
        )
        or {}
    )

    valor_anterior = (
        cpu_anterior.get(
            "uso_percentual"
        )
    )

    valor_atual = (
        cpu_atual.get(
            "uso_percentual"
        )
    )

    if (
        isinstance(
            valor_anterior,
            (int, float),
        )
        and
        isinstance(
            valor_atual,
            (int, float),
        )
    ):

        delta = abs(
            valor_atual
            - valor_anterior
        )

        if delta >= LIMITE_CPU:

            direcao = (
                "aumento"
                if valor_atual > valor_anterior
                else "redução"
            )

            eventos.append(
                criar_evento(
                    "cpu.uso_percentual",
                    valor_anterior,
                    valor_atual,
                    (
                        f"mudança significativa "
                        f"de CPU ({direcao})"
                    ),
                )
            )

    # --------------------------------------------------------
    # MEMÓRIA
    # --------------------------------------------------------

    memoria_anterior = (
        corpo_anterior.get(
            "memoria"
        )
        or {}
    )

    memoria_atual = (
        corpo_atual.get(
            "memoria"
        )
        or {}
    )

    valor_anterior = (
        memoria_anterior.get(
            "uso_percentual"
        )
    )

    valor_atual = (
        memoria_atual.get(
            "uso_percentual"
        )
    )

    if (
        isinstance(
            valor_anterior,
            (int, float),
        )
        and
        isinstance(
            valor_atual,
            (int, float),
        )
    ):

        delta = abs(
            valor_atual
            - valor_anterior
        )

        if delta >= LIMITE_RAM:

            direcao = (
                "aumento"
                if valor_atual > valor_anterior
                else "redução"
            )

            eventos.append(
                criar_evento(
                    "memoria.uso_percentual",
                    valor_anterior,
                    valor_atual,
                    (
                        f"mudança significativa "
                        f"de memória ({direcao})"
                    ),
                )
            )

    # --------------------------------------------------------
    # GPU
    # --------------------------------------------------------

    gpus_anterior = (
        corpo_anterior.get(
            "gpu",
            []
        )
    )

    gpus_atual = (
        corpo_atual.get(
            "gpu",
            []
        )
    )

    if (
        gpus_anterior
        and gpus_atual
    ):

        gpu_anterior = (
            gpus_anterior[0]
        )

        gpu_atual = (
            gpus_atual[0]
        )

        valor_anterior = (
            gpu_anterior.get(
                "uso_percentual"
            )
        )

        valor_atual = (
            gpu_atual.get(
                "uso_percentual"
            )
        )

        if (
            isinstance(
                valor_anterior,
                (int, float),
            )
            and
            isinstance(
                valor_atual,
                (int, float),
            )
        ):

            delta = abs(
                valor_atual
                - valor_anterior
            )

            if delta >= LIMITE_GPU:

                direcao = (
                    "aumento"
                    if valor_atual
                    > valor_anterior
                    else "redução"
                )

                eventos.append(
                    criar_evento(
                        "gpu.uso_percentual",
                        valor_anterior,
                        valor_atual,
                        (
                            f"mudança significativa "
                            f"de GPU ({direcao})"
                        ),
                    )
                )

        # ----------------------------------------------------
        # TEMPERATURAS GPU
        # ----------------------------------------------------

        temperaturas_anterior = (
            gpu_anterior.get(
                "temperaturas",
                []
            )
        )

        temperaturas_atual = (
            gpu_atual.get(
                "temperaturas",
                []
            )
        )

        limite = min(
            len(
                temperaturas_anterior
            ),
            len(
                temperaturas_atual
            ),
        )

        for indice in range(
            limite
        ):

            antiga = (
                temperaturas_anterior[
                    indice
                ]
            )

            nova = (
                temperaturas_atual[
                    indice
                ]
            )

            valor_anterior = antiga.get(
                "temperatura_c"
            )

            valor_atual = nova.get(
                "temperatura_c"
            )

            if not (
                isinstance(
                    valor_anterior,
                    (int, float),
                )
                and
                isinstance(
                    valor_atual,
                    (int, float),
                )
            ):
                continue

            delta = abs(
                valor_atual
                - valor_anterior
            )

            if delta >= LIMITE_TEMPERATURA:

                rotulo = (
                    nova.get(
                        "rotulo"
                    )
                    or nova.get(
                        "sensor"
                    )
                    or f"sensor_{indice}"
                )

                direcao = (
                    "aumento"
                    if valor_atual
                    > valor_anterior
                    else "redução"
                )

                eventos.append(
                    criar_evento(
                        (
                            "gpu.temperaturas."
                            f"{rotulo}"
                        ),
                        valor_anterior,
                        valor_atual,
                        (
                            f"mudança significativa "
                            f"de temperatura ({direcao})"
                        ),
                    )
                )

    return eventos


# ============================================================
# MEMÓRIA CORPORAL
# ============================================================

def carregar_memoria_corporal():

    if not os.path.exists(
        ARQUIVO_MEMORIA_CORPORAL
    ):
        return {
            "identidade": {
                "nome": NOME
            },

            "sessao": {
                "iniciada_em": agora_iso(),

                "ciclos": 0,

                "eventos": [],
            },
        }

    try:

        with open(
            ARQUIVO_MEMORIA_CORPORAL,
            "r",
            encoding="utf-8",
        ) as arquivo:

            memoria = json.load(
                arquivo
            )

        if not isinstance(
            memoria,
            dict,
        ):
            raise ValueError

        memoria.setdefault(
            "identidade",
            {
                "nome": NOME
            },
        )

        memoria.setdefault(
            "sessao",
            {},
        )

        memoria[
            "sessao"
        ].setdefault(
            "ciclos",
            0,
        )

        memoria[
            "sessao"
        ].setdefault(
            "eventos",
            [],
        )

        return memoria

    except (
        OSError,
        json.JSONDecodeError,
        ValueError,
    ):

        return {
            "identidade": {
                "nome": NOME
            },

            "sessao": {
                "iniciada_em": agora_iso(),

                "ciclos": 0,

                "eventos": [],
            },
        }


def salvar_memoria_corporal(
    memoria,
):

    temporario = (
        ARQUIVO_MEMORIA_CORPORAL
        + ".tmp"
    )

    with open(
        temporario,
        "w",
        encoding="utf-8",
    ) as arquivo:

        json.dump(
            memoria,
            arquivo,
            ensure_ascii=False,
            indent=2,
        )

    os.replace(
        temporario,
        ARQUIVO_MEMORIA_CORPORAL,
    )


