def ler_texto(caminho):
    try:

        with open(
            caminho,
            "r",
            encoding="utf-8",
        ) as arquivo:

            return arquivo.read().strip()

    except (
        OSError,
        UnicodeDecodeError,
    ):

        return None


def ler_inteiro(caminho):

    valor = ler_texto(
        caminho
    )

    if valor is None:
        return None

    try:

        return int(
            valor
        )

    except ValueError:

        return None


# ============================================================
# CPU
# ============================================================

def ler_cpu():

    linhas = ler_texto(
        "/proc/stat"
    )

    if not linhas:
        return None

    for linha in linhas.splitlines():

        if not linha.startswith(
            "cpu "
        ):
            continue

        partes = linha.split()

        try:

            valores = [
                int(valor)
                for valor in partes[1:8]
            ]

        except ValueError:

            return None

        if len(valores) < 7:
            return None

        return valores

    return None


def calcular_uso_cpu(
    anterior,
    atual,
):

    if (
        anterior is None
        or atual is None
    ):
        return None

    total_anterior = sum(
        anterior
    )

    total_atual = sum(
        atual
    )

    idle_anterior = (
        anterior[3]
        + anterior[4]
    )

    idle_atual = (
        atual[3]
        + atual[4]
    )

    total_delta = (
        total_atual
        - total_anterior
    )

    idle_delta = (
        idle_atual
        - idle_anterior
    )

    if total_delta <= 0:
        return None

    uso = (
        1
        - (
            idle_delta
            / total_delta
        )
    ) * 100

    uso = max(
        0.0,
        min(
            100.0,
            uso,
        )
    )

    return round(
        uso,
        2,
    )


def classificar_cpu(
    uso,
):

    if uso is None:
        return "indisponivel"

    if uso < 20:
        return "baixa_carga"

    if uso < 60:
        return "carga_moderada"

    if uso < 85:
        return "carga_alta"

    return "carga_muito_alta"


