# ============================================================

def ler_memoria():

    texto = ler_texto(
        "/proc/meminfo"
    )

    if not texto:
        return None

    valores = {}

    for linha in texto.splitlines():

        partes = linha.split()

        if len(partes) < 2:
            continue

        chave = partes[0].rstrip(
            ":"
        )

        try:

            valor_kb = int(
                partes[1]
            )

        except ValueError:

            continue

        valores[
            chave
        ] = valor_kb

    total = valores.get(
        "MemTotal"
    )

    disponivel = valores.get(
        "MemAvailable"
    )

    if (
        total is None
        or disponivel is None
    ):
        return None

    usado = (
        total
        - disponivel
    )

    percentual = (
        usado
        / total
    ) * 100

    return {
        "total_gb": round(
            total
            / 1024
            / 1024,
            2,
        ),

        "disponivel_gb": round(
            disponivel
            / 1024
            / 1024,
            2,
        ),

        "usado_gb": round(
            usado
            / 1024
            / 1024,
            2,
        ),

        "uso_percentual": round(
            percentual,
            2,
        ),

        "estado": (
            classificar_memoria(
                percentual
            )
        ),
    }


def classificar_memoria(
    uso,
):

    if uso < 50:
        return "normal"

    if uso < 75:
        return "uso_moderado"

    if uso < 90:
        return "uso_alto"

    return "uso_muito_alto"


