def ler_uevent(
    caminho,
):

    texto = ler_texto(
        caminho
    )

    if not texto:
        return {}

    resultado = {}

    for linha in texto.splitlines():

        if "=" not in linha:
            continue

        chave, valor = (
            linha.split(
                "=",
                1,
            )
        )

        resultado[
            chave
        ] = valor

    return resultado


