def ler_temperaturas_gpu(
    device,
):

    temperaturas = []

    hwmon_base = os.path.join(
        device,
        "hwmon",
    )

    caminhos_hwmon = sorted(
        glob.glob(
            os.path.join(
                hwmon_base,
                "hwmon*",
            )
        )
    )

    for hwmon in caminhos_hwmon:

        nome_chip = ler_texto(
            os.path.join(
                hwmon,
                "name",
            )
        )

        sensores = sorted(
            glob.glob(
                os.path.join(
                    hwmon,
                    "temp*_input",
                )
            )
        )

        for entrada in sensores:

            valor = ler_inteiro(
                entrada
            )

            if valor is None:
                continue

            nome_sensor = os.path.basename(
                entrada
            )

            numero = nome_sensor[
                4:-6
            ]

            rotulo = ler_texto(
                os.path.join(
                    hwmon,
                    f"temp{numero}_label",
                )
            )

            temperatura = round(
                valor / 1000,
                2,
            )

            temperaturas.append(
                {
                    "sensor": nome_sensor,
                    "rotulo": rotulo,
                    "chip": nome_chip,
                    "temperatura_c": temperatura,
                    "estado": (
                        classificar_temperatura(
                            temperatura
                        )
                    ),
                }
            )

    return temperaturas


