            {
                "zona": os.path.basename(
                    caminho.rstrip("/")
                ),

                "tipo": tipo,

                "temperatura_c": (
                    temperatura
                ),

                "estado": (
                    classificar_temperatura(
                        temperatura
                    )
                ),
            }
        )

    return resultados


