                "consulta": (
                    "capacidades_nixal.json"
                )
            },
        )
    )

    print(
        json.dumps(
            validacao,
            ensure_ascii=False,
            indent=2,
        )
    )

    print()
    print("=" * 60)
    print(
        "TESTE DE OPERAÇÃO INEXISTENTE"
    )
    print("=" * 60)

    inexistente = (
        registro.obter_especificacao(
            "operacao_inexistente"
        )
    )

    print(
        json.dumps(
            {
                "encontrada": (
                    inexistente is not None
                )
            },
            ensure_ascii=False,
